style.css:
@-moz-document domain("gemini.google.com") {
/* =========================================
       1. GENEL ARKA PLAN (Pastel Pembe)
    ========================================= */
    body, 
    main, 
    header, 
    .input-area-container, /* Yazı yazdığın kutunun kendisi */
    .chat-history-container {
        background-color: #fff0f5 !important; /* Çok açık pembe */
    }

    /* =========================================
       2. GEMINI LOGOSUNU MY MELODY YAPMA
    ========================================= */
    /* Orijinal "Gemini" yazısını/logosunu gizle */
    a[aria-label="Gemini"] svg,
    .assistant-symbol {
        display: none !important;
    }

    /* Logo yerine My Melody GIF'ini yerleştir */
    a[aria-label="Gemini"]::before {
        content: "" !important;
        display: inline-block !important;
        /* Senin gönderdiğin GIF linki */
        background-image: url('https://i.pinimg.com/originals/a3/cd/6b/a3cd6b82cdeae466a391b9d838054d2a.gif') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        width: 80px !important; /* Boyutu görseldeki gibi büyük */
        height: 80px !important;
        vertical-align: middle !important;
    }

    /* =========================================
       3. SİMGELERİ ÇİLEK YAPMA
    ========================================= */
    /* Tüm alt çubuktaki simgeleri hedefler (Artı, Mikrofon, Gönder) */
    .input-area-container button mat-icon,
    .input-area-container button .google-symbols,
    button[aria-label*="Gönder"] mat-icon {
        color: transparent !important; /* Orijinal simgeyi görünmez yap */
        /* Senin gönderdiğin çilek linki (PNG olması daha iyi görünür) */
        background-image: url('https://i.pinimg.com/originals/a1/3b/9c/a13b9c83690d6389779930f2c419356f.png') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        width: 28px !important; /* Çilek boyutu */
        height: 28px !important;
        display: inline-block !important;
    }
    
    /* Ataş (Dosya Yükle) simgesini ayrıca hedefleyip gizleyelim veya çilek yapalım */
    /* Eğer ataşın kalmasını istiyorsan bu bloğu sil. Çilek olsun istiyorsan kalsın. */
    button[aria-label*="Dosya yükle"] mat-icon {
         background-image: url('https://i.pinimg.com/originals/a1/3b/9c/a13b9c83690d6389779930f2c419356f.png') !important;
    }
}
